-- Keyword-to-content workflow and per-page content/SEO for geography pages. Run ONE statement at a time in D1 Studio.
CREATE TABLE IF NOT EXISTS seo_keywords (id INTEGER PRIMARY KEY AUTOINCREMENT, keyword TEXT NOT NULL, intent TEXT NOT NULL DEFAULT 'commercial', target_type TEXT NOT NULL DEFAULT 'none', target_path TEXT NOT NULL DEFAULT '', category_slug TEXT NOT NULL DEFAULT '', country_slug TEXT NOT NULL DEFAULT '', place TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'idea', notes TEXT NOT NULL DEFAULT '', created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE UNIQUE INDEX IF NOT EXISTS seo_keywords_uq ON seo_keywords (keyword);
CREATE TABLE IF NOT EXISTS geo_page_content (path TEXT PRIMARY KEY, seo_title TEXT NOT NULL DEFAULT '', meta_description TEXT NOT NULL DEFAULT '', intro TEXT NOT NULL DEFAULT '', primary_keyword TEXT NOT NULL DEFAULT '', secondary_keywords TEXT NOT NULL DEFAULT '', updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
